import{_ as l,o as i,c as e,ae as t}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"帳單拆分說明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/09-bill-split-guide.md","filePath":"v1/zh-HK/guide/09-bill-split-guide.md"}'),r={name:"v1/zh-HK/guide/09-bill-split-guide.md"};function o(h,a,d,n,s,u){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="帳單拆分說明" tabindex="-1">帳單拆分說明 <a class="header-anchor" href="#帳單拆分說明" aria-label="Permalink to &quot;帳單拆分說明&quot;">​</a></h1><h2 id="_1-這是什麼功能" tabindex="-1">1. 這是什麼功能 <a class="header-anchor" href="#_1-這是什麼功能" aria-label="Permalink to &quot;1. 這是什麼功能&quot;">​</a></h2><p>當一筆消費同時包含多個用途（例如「超市購物」同時買了水果和日用品），你可以把這筆帳單拆成多筆子帳單，讓分類統計更準確。</p><p>拆分完成後：</p><ul><li>你會看到多筆「子帳單」（每筆都有自己的分類、金額、備註）。</li><li>原本那筆帳單會變成「拆分容器」，不再參與列表顯示與統計匯總，避免金額重複計算。</li></ul><h2 id="_2-適用場景" tabindex="-1">2. 適用場景 <a class="header-anchor" href="#_2-適用場景" aria-label="Permalink to &quot;2. 適用場景&quot;">​</a></h2><ul><li>一筆付款包含多個類別（餐飲 + 日用品、交通 + 停車等）</li><li>需要更精細的分類統計、預算對比</li><li>同一張收據想拆到不同分類/標籤</li></ul><h2 id="_3-如何使用" tabindex="-1">3. 如何使用 <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用&quot;">​</a></h2><ol><li>進入「帳單列表」找到要拆分的帳單</li><li>對該帳單左滑，選擇「拆分」</li><li>在「拆分帳單」頁面中： <ul><li>點選子項的「分類」選擇需要的收支項目</li><li>點選「金額」輸入每個子項的金額</li><li>備註可選填（用作補充說明）</li><li>需要更多項目時，點選「新增一項」</li></ul></li><li>確保「剩餘待分配金額」為 0（表示子項合計剛好等於原始帳單金額）</li><li>點選右上角「完成/儲存」提交</li></ol><h2 id="_4-使用規則與注意事項" tabindex="-1">4. 使用規則與注意事項 <a class="header-anchor" href="#_4-使用規則與注意事項" aria-label="Permalink to &quot;4. 使用規則與注意事項&quot;">​</a></h2><ul><li>子項金額合計必須等於原始帳單金額，否則無法儲存。</li><li>每一條子項都需要選擇分類，且金額必須大於 0。</li><li>拆分後的統計口徑以子帳單為準；原始帳單不再計入統計。</li><li>支援多級拆分：子帳單也可以再拆分；最終統計以最末級子帳單為準。</li><li>拆分與報銷互斥：已標記「可報銷/待報銷/已報銷」的支出帳單不能拆分；已拆分的帳單也無法開啟報銷流程。建議先確認這筆支出是否需要走報銷，再決定是否拆分。</li></ul><h2 id="_5-常見問題" tabindex="-1">5. 常見問題 <a class="header-anchor" href="#_5-常見問題" aria-label="Permalink to &quot;5. 常見問題&quot;">​</a></h2><h3 id="q1-拆分後原本的帳單去哪了" tabindex="-1">Q1：拆分後原本的帳單去哪了？ <a class="header-anchor" href="#q1-拆分後原本的帳單去哪了" aria-label="Permalink to &quot;Q1：拆分後原本的帳單去哪了？&quot;">​</a></h3><p>為了避免金額重複統計，原本的帳單會被標記為「拆分容器」，通常不會在列表中顯示；實際統計會以拆分後的子帳單為準。</p><h3 id="q2-可以只拆一部分嗎" tabindex="-1">Q2：可以只拆一部分嗎？ <a class="header-anchor" href="#q2-可以只拆一部分嗎" aria-label="Permalink to &quot;Q2：可以只拆一部分嗎？&quot;">​</a></h3><p>可以。你可以把其中一項保留為「其他/原分類」，金額填寫為剩餘金額即可。重點是所有子項金額合計必須等於原始金額。</p><h3 id="q3-拆分後還能修改嗎" tabindex="-1">Q3：拆分後還能修改嗎？ <a class="header-anchor" href="#q3-拆分後還能修改嗎" aria-label="Permalink to &quot;Q3：拆分後還能修改嗎？&quot;">​</a></h3><p>一般建議直接修改拆分後的子帳單（金額/分類/備註等）。如果需要重新拆分，通常做法是先刪除相關子帳單再重新操作。</p>',18)])])}const p=l(r,[["render",o]]);export{c as __pageData,p as default};
